WITH recent_employees AS (SELECT *, TRIM(job_title) AS clean_job_title FROM employees WHERE NOT (manager_id IN (8, 24, 27, 34) AND hire_date <= '2024-07-13')), employees_stats AS (SELECT level, ROUND((100 * SUM(CASE WHEN job_title = 'Designer' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_designer, SUM(CASE WHEN level = 'L2' THEN 1 ELSE 0 END) AS l2_count FROM recent_employees GROUP BY level) SELECT level, l2_count FROM employees_stats WHERE l2_count < 35
